Mesh<Point, double> mesh;
std::vector<std::vector<std::size_t>> faces;
std::vector<Point> vertices;

auto const& cells = rt.finite_cells();
for (auto const& cell : cells) {
    auto const& face = rt.power_diagram_faces(cell);
    if (face.size() == 3) {  // Only consider triangular faces
        for (std::size_t i = 0; i < 3; ++i) {
            auto const& edge = face[i];
            if (edge.first != edge.second) {  // Skip degenerate edges
                auto const& p1 = rt.tetrahedron(edge.first).vertex(0);
                auto const& p2 = rt.tetrahedron(edge.second).vertex(0);
                double dist = std::sqrt(std::pow(p1.x() - p2.x(), 2) +
                                       std::pow(p1.y() - p2.y(), 2) +
                                       std::pow(p1.z() - p2.z(), 2));
                if (dist >= threshold) {
                    vertices.push_back(p1);
                    vertices.push_back(p2);
                    faces.push_back({vertices.size() - 2, vertices.size() - 1});
                }
            }
        }
    }
}

mesh.vertices = std::move(vertices);
mesh.faces = std::move(faces);
// END_CODE

